<!--
  上传图片组件 - UploadImage
  
  实现思路：
  1. 组件状态管理：维护上传状态（空闲、上传中、上传成功、上传失败）
  2. 文件处理：支持拖拽和点击两种上传方式，验证文件类型和大小
  3. 上传逻辑：使用 uploadImage API 进行图片上传，获取图片尺寸信息
  4. 界面显示：根据不同状态显示不同的界面（空状态、上传中、预览）
  5. 事件处理：上传成功后通过 emit 向父组件传递结果，失败则显示错误提示
  
  功能特性：
  - 支持拖拽上传和点击上传
  - 文件类型验证（仅支持图片格式）
  - 文件大小验证（最大4.5MB）
  - 上传进度显示
  - 图片预览
  - 响应式设计
-->

<template>
  <div class="upload-image-container" >
    <div 
    :style="convertStyleObject({ width: width, height: height })"
    :class="{ 'drag-over': isDragOver, 'uploading': isUploading, 'uploaded': isUploaded }"
    @drop="handleDrop"
    @dragover.prevent="handleDragOver"
    @dragleave="handleDragLeave"
    @click="handleClick"
  >
    <!-- 空状态 - 显示上传提示 -->
    <div v-if="!isUploading && !isUploaded" class="upload-placeholder">
      <!-- 上传图标 -->
      <div class="upload-icon">
        <l-img 
            src="/static/images/upload_arrow.png" 
            w="40px" 
            h="40px" 
          />
      </div>
      
      <!-- 主要提示文字 -->
      <div class="upload-text-primary">
        {{ $t('clickOrTapToUpload') }}
      </div>
      
      <!-- 辅助提示文字 -->
      <div class="upload-text-secondary">
        {{ $t('fileSizeLimit') }}
      </div>
    </div>

    <!-- 上传中状态 -->
    <div v-if="isUploading" class="upload-loading">
      <div class="loading-icon">
        <div class="loading-icon-container">
        </div>
      </div>
      <div class="loading-text">
        {{ $t('uploading') }}
      </div>
    </div>

    <!-- 上传成功状态 - 显示图片预览 -->
    <div v-if="isUploaded && imagePreviewUrl" class="upload-success">
      <!-- 图片预览容器 -->
      <div class="preview-container">
        <l-img 
          @click.stop="handleReupload"
          :src="imagePreviewUrl" 
          :w="previewImageSize.width" 
          :h="previewImageSize.height" 
          class="preview-image"
          style="overflow: visible;"
          fit="contain"
        />
        <!-- 删除图标 -->
        <div class="delete-icon" @click.stop="handleDeleteImage">
          <l-img 
            src="/static/images/modal-close.png" 
            w="32px" 
            h="32px" 
          />
        </div>
      </div>
    </div>

    <!-- 隐藏的文件输入框 -->
    <input 
      ref="fileInputRef"
      type="file"
      accept="image/*"
      @change="handleFileSelect"
      style="display: none"
    />
  </div>
  </div>
</template>

<script setup>
import { ref, computed,watch } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import { uploadImage } from '@/api/upload/upload-service';
import { getImageDimensions } from '@/utils/util';
import { showMessageError } from '@/utils/ui-feedback';
import { ALLOWED_FILE_TYPES } from "@/types/upload";
import { convertStyleObject, pxToRem } from '@/utils/px-to-rem';

// 组件属性定义
const props = defineProps({
  // 组件宽度，默认100%
  width: {
    type: String,
    default: '100%'
  },
  // 组件高度，默认100%
  height: {
    type: String,
    default: '100%'
  },
  // 最大文件大小（MB），默认4.5MB
  maxSize: {
    type: Number,
    default: 4.5
  },
  // 是否需要压缩，默认true
  needCompression: {
    type: Boolean,
    default: true
  },
  // 默认图片地址，如果有值则直接显示该图片
  defaultUrl: {
    type: String,
    default: ''
  }
});

// 组件事件定义
const emit = defineEmits(['uploadSuccess', 'deleteSuccess']);

// 多语言支持
const { t } = useI18n();

watch(props, (newVal) => {
  if (newVal.defaultUrl&&!imagePreviewUrl.value) {
    initDefaultImage();
  }
});

// 组件状态
const isDragOver = ref(false); // 是否正在拖拽
const isUploading = ref(false); // 是否正在上传
const isUploaded = ref(false); // 是否已上传成功
const imagePreviewUrl = ref(''); // 图片预览URL
const fileInputRef = ref(null); // 文件输入框引用
const isReuploadMode = ref(false); // 是否处于重新上传模式

/**
 * 计算预览图片的尺寸
 * 确保最短边距离容器边缘20px
 */
const previewImageSize = computed(() => {
  // 检查宽度是否为数字
  const widthIsNumber = !isNaN(props.width) && props.width > 0;
  const heightIsNumber = !isNaN(props.height) && props.height > 0;
  
  let finalWidth, finalHeight;
  
  if (widthIsNumber) {
    // 宽度是数字，按当前逻辑处理
    const containerWidth = parseInt(props.width);
    const margin = 20;
    const maxWidth = containerWidth - margin * 2;
    finalWidth = pxToRem(Math.max(maxWidth, 40) + 'px');
  } else {
    // 宽度不是数字，直接返回原值
    finalWidth = props.width;
  }
  if (heightIsNumber) {
    console.log('heightIsNumber', props.height);
    // 高度是数字，按当前逻辑处理
    const containerHeight = parseInt(props.height);
    const margin = 20;
    const maxHeight = containerHeight - margin * 2;
    finalHeight = pxToRem(Math.max(maxHeight, 40) + 'px');
  } else {
    // 高度不是数字，直接返回原值
    finalHeight = props.height;
  }
  console.log(finalWidth, finalHeight);
  return {
    width: pxToRem(finalWidth),
    height: pxToRem(finalHeight)
  };
});

/**
 * 验证文件是否符合要求
 * @param {File} file - 要验证的文件
 * @returns {boolean} - 验证结果
 */
const validateFile = (file) => {
  // 检查文件类型
  if (!ALLOWED_FILE_TYPES.IMAGE.includes(file.type)) {
    showMessageError(t("fileTypeNotAllowedWithName", { name: file.name }));
    return false;
  }

  // 检查文件大小
  const maxSizeBytes = props.maxSize * 1024 * 1024; // 转换为字节
  if (file.size > maxSizeBytes) {
    showMessageError(t('fileSizeExceedsLimit', { size: props.maxSize }));
    return false;
  }

  return true;
};

/**
 * 处理文件上传
 * @param {File} file - 要上传的文件
 */
const handleFileUpload = async (file) => {
  if (!validateFile(file)) {
    return;
  }

  try {
    // 如果是重新上传模式，先清理旧的预览URL
    if (isReuploadMode.value && imagePreviewUrl.value) {
      if (imagePreviewUrl.value.startsWith('blob:')) {
        URL.revokeObjectURL(imagePreviewUrl.value);
      }
      imagePreviewUrl.value = '';
    }

    // 设置上传状态
    isUploading.value = true;
    isUploaded.value = false;
    isReuploadMode.value = false; // 重置重新上传模式

    // 创建预览URL
    imagePreviewUrl.value = URL.createObjectURL(file);

    // 获取图片尺寸信息
    const dimensions = await getImageDimensions(imagePreviewUrl.value);

    // 执行上传
    const uploadResult = await uploadImage(file, props.needCompression, dimensions);

    // 上传成功
    isUploading.value = false;
    isUploaded.value = true;

    // // 更新预览URL为服务器URL
    // if (uploadResult.url) {
    //   // 释放临时预览URL
    //   URL.revokeObjectURL(imagePreviewUrl.value);
    //   imagePreviewUrl.value = uploadResult.url;
    // }

    // 通知父组件上传成功
    emit('uploadSuccess', {
      url: uploadResult.url,
      mediaId: uploadResult.mediaId,
      dimensions: dimensions,
      originalFile: file
    });

  } catch (error) {
    console.error('Image upload failed:', error);
    
    // 重置状态
    isUploading.value = false;
    isUploaded.value = false;
    isReuploadMode.value = false;
    
    // 释放预览URL
    if (imagePreviewUrl.value) {
      URL.revokeObjectURL(imagePreviewUrl.value);
      imagePreviewUrl.value = '';
    }

    // 显示错误提示
    showMessageError(t('uploadFailed'));
  }
};

/**
 * 初始化默认图片
 */
const initDefaultImage = () => {
  if (props.defaultUrl) {
    imagePreviewUrl.value = props.defaultUrl;
    isUploaded.value = true;
    isUploading.value = false;
    
    // 通知父组件默认图片加载成功
    emit('uploadSuccess', {
      url: props.defaultUrl,
      mediaId: null,
      dimensions: null,
      originalFile: null,
      isDefault: true
    });
  }
};

/**
 * 处理点击上传
 */
const handleClick = () => {
  if (isUploading.value || isUploaded.value) return;
  fileInputRef.value?.click();
};

/**
 * 处理文件选择
 * @param {Event} event - 文件选择事件
 */
const handleFileSelect = (event) => {
  const file = event.target.files?.[0];
  if (file) {
    handleFileUpload(file);
  }
  // 重置文件输入框，允许重复选择同一文件
  event.target.value = '';
};

/**
 * 处理拖拽进入
 * @param {DragEvent} event - 拖拽事件
 */
const handleDragOver = (event) => {
  event.preventDefault();
  if (!isUploading.value) {
    isDragOver.value = true;
  }
};

/**
 * 处理拖拽离开
 */
const handleDragLeave = () => {
  isDragOver.value = false;
};

/**
 * 处理文件拖拽释放
 * @param {DragEvent} event - 拖拽释放事件
 */
const handleDrop = (event) => {
  event.preventDefault();
  isDragOver.value = false;
  
  if (isUploading.value) return;
  
  const files = event.dataTransfer?.files;
  if (files && files.length > 0) {
    handleFileUpload(files[0]);
  }
};

/**
 * 处理重新上传
 */
const handleReupload = () => {
  // 设置重新上传模式，不立即清空图片
  isReuploadMode.value = true;
  
  // 触发文件选择
  fileInputRef.value?.click();
};

/**
 * 处理删除图片
 */
const handleDeleteImage = () => {
  // 释放blob URL
  if (imagePreviewUrl.value && imagePreviewUrl.value.startsWith('blob:')) {
    URL.revokeObjectURL(imagePreviewUrl.value);
  }
  
  // 重置所有状态
  isUploading.value = false;
  isUploaded.value = false;
  imagePreviewUrl.value = '';
  isReuploadMode.value = false;
  
  // 重置文件输入框
  if (fileInputRef.value) {
    fileInputRef.value.value = '';
  }
  
  emit('deleteSuccess');
};

// 组件生命周期
import { onMounted, onUnmounted } from 'vue';

onMounted(() => {
  // 初始化默认图片
  initDefaultImage();
});

onUnmounted(() => {
  if (imagePreviewUrl.value && imagePreviewUrl.value.startsWith('blob:')) {
    URL.revokeObjectURL(imagePreviewUrl.value);
  }
});

// 暴露方法给父组件
defineExpose({
  handleDeleteImage
});
</script>

